const STORE='dailyEnglish.v1',AUTH_KEY='dailyEnglish.accounts.v1';const legacyAccountId=sessionStorage.getItem('dailyEnglish.session')||null;const initial={saved:[],learned:[],wrong:[],customWords:[],minutes:0,days:[],lastVisit:null,chats:{free:[],scenario:[]},assessments:[],level:'A1',levelLabel:'초급',manualLevel:false};let currentAccount=null,firebaseUser=null,authInitialized=false;let state;try{const old=JSON.parse(localStorage.getItem(legacyAccountId?`${STORE}.${legacyAccountId}`:STORE)||'{}');state={...initial,...old,chats:{...initial.chats,...(old.chats||{})}}}catch{state={...initial}};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];let currentFilter='all',quizOrder=[],quizIndex=0,quizScore=0,answered=false,toastTimer,chatMode='free',recognition=null,listening=false,chatBusy=false;
function persist(){localStorage.setItem(currentAccount?`${STORE}.${currentAccount}`:STORE,JSON.stringify(state));if(currentAccount){const accounts=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}');if(accounts[currentAccount]){accounts[currentAccount].data=state;localStorage.setItem(AUTH_KEY,JSON.stringify(accounts))}}renderStats();if(typeof renderAccountHeader==='function')renderAccountHeader()}
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function renderStats(){const now=new Date(),today=dateKey(),days=state.days||[];if(state.lastVisit!==today){if(state.lastVisit){const prev=new Date(`${state.lastVisit}T12:00:00`),diff=Math.round((new Date(`${today}T12:00:00`)-prev)/86400000);if(diff>1)state.days=days.filter(x=>x>=dateKey(new Date(now.getTime()-6*86400000)))}state.lastVisit=today;localStorage.setItem(STORE,JSON.stringify(state))}const activeDays=new Set(state.days||[]);const week=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);week.push(dateKey(d))}$('#weekDots').innerHTML=week.map(d=>`<span class="${activeDays.has(d)?'done':''}"></span>`).join('');let streak=0;for(let i=0;i<365;i++){const d=new Date();d.setDate(d.getDate()-i);if(activeDays.has(dateKey(d)))streak++;else if(i===0)continue;else break}$('#streakCount').textContent=streak;$('#todayStat').textContent=streak;$('#minutesStat').textContent=state.minutes||0;$('#wordsStat').textContent=(state.learned||[]).length;const totalWords=allWords().length,learnedCount=(state.learned||[]).length;$('#ringPercent').textContent=`${Math.round((learnedCount/Math.max(1,totalWords))*100)}%`;const deg=Math.min(360,learnedCount/Math.max(1,totalWords)*360);$('#progressRing').style.background=`conic-gradient(var(--primary-600) ${deg}deg,var(--gray-200) ${deg}deg)`;$('#wordsTotalNote').textContent=`총 ${totalWords.toLocaleString('ko-KR')}개 중`;$('#allCount').textContent=totalWords;$('#todayWordSummary').textContent=`${getTodayWords().length}개의 새 단어 · ${state.level||'A1'} 난이도`;$('#savedCount').textContent=(state.saved||[]).length;$('#wordStatus').textContent=(state.learned||[]).length?'진행 중':'시작 전'}
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
const titles={home:'오늘의 학습',words:'단어장',study:'단어 공부',quiz:'퀴즈 연습',talk:'AI 영어 대화',assessment:'수준 진단',result:'진단 결과',mypage:'마이페이지'};function go(view){$$('.view').forEach(x=>x.classList.remove('active'));$(`#${view}View`).classList.add('active');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumbTitle').textContent=titles[view];if(view==='words')renderWords();if(view==='study')renderStudy();if(view==='quiz'&&quizOrder.length===0)startQuiz();if(view==='talk')renderChat();if(view==='assessment')renderAssessmentIntro();if(view==='result')renderLatestResult();if(view==='mypage')renderMyPage();window.scrollTo({top:0,behavior:'smooth'})}
function allWords(){const extras=state.customWords||[];return [...WORDS,...extras]}
function addSaved(id){if(!state.saved.includes(id)){state.saved.push(id);persist()}}
function saveCustomWord(en,ko){let item=(state.customWords||[]).find(w=>w.en.toLowerCase()===en.toLowerCase());if(!item){item={id:`custom-${Date.now()}`,en,ko,type:'phrase',example:en,translation:ko};state.customWords.push(item)}addSaved(item.id)}
function renderWords(){let q=$('#wordSearch').value.trim().toLowerCase();let all=allWords();let data=all.filter(w=>(currentFilter==='all'||state.saved.includes(w.id))&&(!q||`${w.en} ${w.ko} ${w.example||''}`.toLowerCase().includes(q)));$('#wordGrid').innerHTML=data.length?data.map(w=>`<article class="word-card"><div><div class="word-top"><span class="word-en">${escapeHtml(w.en)}</span><span class="word-type">${escapeHtml(w.type||'phrase')}</span></div><div class="word-meaning">${escapeHtml(w.ko)}</div><div class="word-example"><em>${escapeHtml(w.example||'')}</em><br>${escapeHtml(w.translation||'')}</div></div><div class="word-actions"><button class="small-icon" data-speak="${w.id}" aria-label="${w.en} 발음 듣기">♫</button><button class="small-icon ${state.saved.includes(w.id)?'saved':''}" data-save="${w.id}" aria-label="${w.en} 저장">${state.saved.includes(w.id)?'♥':'♡'}</button></div></article>`).join(''):'<div class="empty-state">아직 저장한 단어가 없어요. 추천 단어의 하트를 눌러 담아보세요.</div>';$$('[data-save]').forEach(b=>b.onclick=()=>toggleSave(+b.dataset.save));$$('[data-speak]').forEach(b=>b.onclick=()=>speak(all.find(w=>w.id===+b.dataset.speak).en))}
function toggleSave(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();renderWords();showToast(state.saved.includes(id)?'내 단어장에 저장했어요':'단어장에서 삭제했어요')}
function speak(text){if(!('speechSynthesis'in window)){showToast('이 브라우저에서는 음성 재생을 지원하지 않아요.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.83;speechSynthesis.speak(u)}
function startQuiz(){quizOrder=[...allWords()].sort(()=>Math.random()-.5).slice(0,5);quizIndex=0;quizScore=0;renderQuiz()}
function renderQuiz(){answered=false;const wrap=$('#quizWrap');if(quizIndex>=quizOrder.length){const pct=Math.round(quizScore/quizOrder.length*100);wrap.innerHTML=`<div class="quiz-card quiz-result"><div class="result-icon">${pct>=60?'✦':'↻'}</div><h2>퀴즈 완료!</h2><p>5문제 중 <b>${quizScore}개</b>를 맞혔어요. ${pct>=60?'좋은 흐름이에요!':'다시 풀면서 기억을 다져봐요.'}</p><div class="result-actions"><button id="retryQuiz">다시 도전하기</button><button id="toWords">단어장 보기</button></div></div>`;$('#quizProgressLabel').textContent='완료';$('#retryQuiz').onclick=startQuiz;$('#toWords').onclick=()=>go('words');return}const w=quizOrder[quizIndex],others=allWords().filter(x=>x.id!==w.id).sort(()=>Math.random()-.5).slice(0,3),options=[...others,w].sort(()=>Math.random()-.5);$('#quizProgressLabel').textContent=`${quizIndex+1} / ${quizOrder.length}`;wrap.innerHTML=`<div class="quiz-card"><div class="quiz-topline"><span>오늘의 단어 퀴즈</span><b>질문 ${quizIndex+1}</b></div><div class="quiz-word">${w.en}</div><div class="quiz-hint">이 단어의 뜻은 무엇일까요?</div><div class="answer-grid">${options.map((x,i)=>`<button class="answer-option" data-answer="${x.id}"><span>${['A','B','C','D'][i]}.</span> ${x.ko}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback"></div><button class="quiz-next" id="quizNext" disabled>${quizIndex===quizOrder.length-1?'결과 보기':'다음 문제'} →</button></div>`;$$('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer,w.id));$('#quizNext').onclick=()=>{quizIndex++;renderQuiz()}}
function answer(id,correct){if(answered)return;answered=true;const ok=id===correct;if(ok)quizScore++;$$('[data-answer]').forEach(b=>{const n=+b.dataset.answer;if(n===correct)b.classList.add('correct');else if(n===id)b.classList.add('wrong');b.disabled=true});const correctWord=allWords().find(w=>w.id===correct);$('#quizFeedback').textContent=ok?'정답이에요! 잘 기억하고 있네요.':`아쉬워요. 정답은 “${correctWord.ko}”예요. 내 단어장에 저장했어요.`;$('#quizNext').disabled=false;if(!state.learned.includes(correct))state.learned.push(correct);if(!ok){if(!state.wrong.includes(correct))state.wrong.push(correct);addSaved(correct)}const today=dateKey();if(!state.days.includes(today))state.days.push(today);state.minutes=(state.minutes||0)+1;persist()}
let studyOrder=[],studyIndex=0,studyRevealed=false;function renderStudy(){const pool=state.saved.length?allWords().filter(w=>state.saved.includes(w.id)):allWords();if(!studyOrder.length)studyOrder=[...pool].sort(()=>Math.random()-.5);if(studyIndex>=studyOrder.length)studyIndex=0;const w=studyOrder[studyIndex];$('#studyShell').innerHTML=`<div class="study-topline"><span>${state.saved.length?'내 단어장 복습':'추천 단어 학습'}</span><span>${studyIndex+1} / ${studyOrder.length}</span></div><article class="study-card ${studyRevealed?'revealed':''}"><div class="study-word-type">${escapeHtml(w.type||'phrase')}</div><h2>${escapeHtml(w.en)}</h2><button class="study-listen" id="studyListen">♫ 발음 듣기</button>${studyRevealed?`<div class="study-answer"><b>${escapeHtml(w.ko)}</b><p>${escapeHtml(w.example||'')}</p><small>${escapeHtml(w.translation||'')}</small></div>`:`<p class="study-prompt">뜻이 생각나면 정답을 확인해보세요.</p><button id="revealWord" class="primary-button">뜻 보기</button>`}</article><div class="study-actions">${studyRevealed?`<button id="studyWrong" class="study-secondary">헷갈렸어요 · 단어장 저장</button><button id="studyKnown" class="primary-button">알고 있어요 →</button>`:`<button class="study-secondary" id="studySkip">나중에 보기</button>`}</div><div class="study-add"><details><summary>새 단어 직접 추가</summary><div class="add-word-form"><input id="newEn" placeholder="영어 단어 또는 표현"/><input id="newKo" placeholder="한국어 뜻"/><button id="addWord" class="primary-button">추가하고 저장</button></div></details></div>`;$('#studyListen').onclick=()=>speak(w.en);const reveal=$('#revealWord');if(reveal)reveal.onclick=()=>{studyRevealed=true;renderStudy()};const skip=$('#studySkip');if(skip)skip.onclick=()=>nextStudy();const wrong=$('#studyWrong');if(wrong)wrong.onclick=()=>{addSaved(w.id);if(!state.wrong.includes(w.id))state.wrong.push(w.id);showToast('헷갈린 단어를 단어장에 저장했어요');nextStudy()};const known=$('#studyKnown');if(known)known.onclick=()=>{if(!state.learned.includes(w.id))state.learned.push(w.id);persist();nextStudy()};$('#addWord').onclick=()=>{const en=$('#newEn').value.trim(),ko=$('#newKo').value.trim();if(!en||!ko){showToast('영어와 뜻을 모두 입력해주세요');return}saveCustomWord(en,ko);showToast('새 단어를 단어장에 추가했어요');studyOrder=[...allWords().filter(x=>state.saved.includes(x.id))];studyIndex=studyOrder.findIndex(x=>x.en===en);studyRevealed=false;renderStudy()}}
function nextStudy(){studyIndex=(studyIndex+1)%studyOrder.length;studyRevealed=false;renderStudy()}
const SCENARIOS={cafe:{title:'카페에서 주문하기',role:'You are a friendly barista. Help the learner order a drink. Ask one short question at a time. Stay in this cafe scenario.',opening:'Hi there! Welcome to our café. What would you like to drink today?',hint:'음료를 주문해보세요. 예: “I’d like a latte, please.”'},airport:{title:'공항에서 체크인하기',role:'You are an airport check-in agent. Help the learner check in for a flight. Ask one short question at a time and stay in this airport scenario.',opening:'Good morning! Where are you flying today?',hint:'목적지나 예약 정보를 영어로 말해보세요.'},hotel:{title:'호텔 체크인하기',role:'You are a helpful hotel receptionist. Help the learner check in. Ask one short question at a time and stay in this hotel scenario.',opening:'Welcome to our hotel! Do you have a reservation?',hint:'예약 여부나 이름을 영어로 답해보세요.'},introductions:{title:'처음 만난 사람과 인사하기',role:'You are a warm, friendly person meeting the learner for the first time. Make small talk and ask one short question at a time.',opening:'Hi! I’m Alex. It’s nice to meet you. What’s your name?',hint:'이름을 말하고 상대방에게도 물어보세요.'}};
function activeScenario(){return SCENARIOS[$('#scenarioSelect').value]}
function renderChat(){const msgs=state.chats[chatMode]||[];$('#chatMessages').innerHTML=msgs.length?msgs.map(m=>`<div class="message-row ${m.role==='user'?'user-row':'ai-row'}"><div class="message-bubble">${escapeHtml(m.text).replace(/\n/g,'<br>')}${m.translation?`<div class="translation">${escapeHtml(m.translation)}</div>`:''}${m.tips?.length?`<div class="tips-list">${m.tips.map(tip=>`<details class="tip-card"><summary><span class="tipbulb">✦</span><b>${escapeHtml(tip.phrase)}</b><span class="tip-meaning">${escapeHtml(tip.meaning)}</span><span class="tip-more">자세히 보기 ⌄</span><button class="tip-save" data-tip="${encodeURIComponent(JSON.stringify(tip))}" type="button">단어장에 저장</button></summary><p>${escapeHtml(tip.detail)}</p></details>`).join('')}</div>`:''}${m.recommended?.length?`<div class="recommended-words"><small>이번 대화 추천 단어</small>${m.recommended.map(id=>{const w=allWords().find(x=>x.id===id);return w?`<button class="recommend-chip ${state.saved.includes(id)?'is-saved':''}" data-recommend="${id}">${escapeHtml(w.en)} · ${escapeHtml(w.ko)} ${state.saved.includes(id)?'♥':'＋'}</button>`:''}).join('')}</div>`:''}${m.role==='assistant'?`<button class="speak-reply" data-utter="${encodeURIComponent(m.text)}" title="음성으로 듣기">♫ 듣기</button>`:''}</div></div>`).join(''):`<div class="chat-welcome"><div class="welcome-spark">✦</div><b>${chatMode==='free'?'무엇이든 영어로 이야기해봐요':'상황 속 주인공이 되어 영어로 답해보세요'}</b><p>${chatMode==='free'?'오늘 있었던 일, 취미, 음식 등 편한 주제로 시작하면 돼요.':'AI가 상황에 맞는 역할로 질문하면 영어로 대답해보세요.'}</p></div>`;$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;$$('[data-utter]').forEach(b=>b.onclick=()=>speak(decodeURIComponent(b.dataset.utter)));$$('[data-tip]').forEach(b=>b.onclick=e=>{e.preventDefault();const tip=JSON.parse(decodeURIComponent(b.dataset.tip));saveCustomWord(tip.phrase,`${tip.meaning} ${tip.detail}`);showToast('오늘 배운 표현을 단어장에 저장했어요')});$$('[data-recommend]').forEach(b=>b.onclick=()=>{addSaved(+b.dataset.recommend);b.classList.add('is-saved');b.textContent=b.textContent.replace('＋','♥');showToast('추천 단어를 단어장에 저장했어요')});$('#scenarioPicker').classList.toggle('visible',chatMode==='scenario');$('#scenarioHint').textContent=activeScenario().hint;$('#chatInput').placeholder=chatMode==='free'?'영어로 자유롭게 이야기해보세요...':'영어로 상황에 맞게 답해보세요...'}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function addMessage(mode,msg){state.chats[mode].push(msg);persist()}
function setBusy(b){chatBusy=b;$('#sendMessage').disabled=b;$('#micButton').disabled=b;$('#speechStatus').textContent=b?'AI가 답변을 생각하고 있어요…':'마이크 버튼을 누르거나 영어 문장을 입력해보세요.'}
function localReply(text){const t=text.toLowerCase();if(chatMode==='scenario'){const key=$('#scenarioSelect').value;if(key==='cafe'){if(/(latte|coffee|tea|drink|juice|물|water)/.test(t))return 'Great choice! What size would you like: small, medium, or large?';if(/(small|medium|large|regular|tall)/.test(t))return 'Perfect. Would you like anything to eat with your drink?';if(/(no thanks|nothing|no,|that is all|that’s all)/.test(t))return 'No problem! Your total is $5.50. You can pay right here.';return 'Of course! Could you tell me what you would like to order?'}if(key==='airport')return /(서울|tokyo|london|new york|paris|flight|reservation|booking)/.test(t)?'Thank you. May I see your passport, please?':'I can help with that. Could you tell me your destination or flight number?';if(key==='hotel')return /(yes|reservation|book|booking|name|네|예약)/.test(t)?'Wonderful. Could I have the name on the reservation, please?':'No problem. Are you checking in for tonight?';return 'That sounds nice! How long have you lived there?'}if(/\b(hello|hi|hey)\b/.test(t))return 'Hi! It’s lovely to chat with you. How has your day been so far?';if(/\b(food|eat|dinner|lunch|breakfast|pizza|coffee)\b/.test(t))return 'That sounds delicious! What do you like most about it?';if(/\b(work|job|study|school)\b/.test(t))return 'That sounds interesting. What do you enjoy most about it?';if(/\b(tired|sad|bad|difficult|hard)\b/.test(t))return 'I’m sorry to hear that. You’re doing a great job expressing yourself in English. What happened?';return 'That’s interesting! Could you tell me a little more about it?'}
async function getAIReply(){const history=state.chats[chatMode],scenario=chatMode==='scenario'?activeScenario():null;try{const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:history.map(m=>({role:m.role,content:m.text})),mode:chatMode,scenario:scenario?{title:scenario.title,role:scenario.role}:null})});if(!res.ok)throw new Error('API unavailable');const data=await res.json();if(!data.reply)throw new Error('Empty reply');return data.reply}catch{return localReply(history[history.length-1].text)}}
async function sendChat(text){const clean=text.trim();if(!clean||chatBusy)return;addMessage(chatMode,{role:'user',text:clean});$('#chatInput').value='';if(chatMode==='scenario'){const today=dateKey();if(!state.days.includes(today))state.days.push(today);state.minutes=(state.minutes||0)+1;persist()}renderChat();setBusy(true);try{const reply=await getAIReply();const tips=[];if(/\b(i am agree|i agree about)\b/i.test(clean))tips.push({phrase:'I agree with you.',meaning:'동의할 때는 agree with + 사람/의견을 써요.',detail:'agree는 전치사 with와 자주 함께 써요. “I agree with you”는 “당신 말에 동의해요”라는 자연스러운 표현입니다.'});if(/\b(i like|i love)\b/i.test(clean))tips.push({phrase:'I’m really into it.',meaning:'좋아하는 취미를 말할 때 유용한 표현이에요.',detail:'be into something은 어떤 활동이나 주제에 관심이 많고 즐긴다는 뜻의 편한 회화 표현이에요.'});if(/\b(please|could you|would like)\b/i.test(clean))tips.push({phrase:'Could I have …, please?',meaning:'정중하게 요청하거나 주문할 때 좋아요.',detail:'“I want”보다 부드러운 요청 표현입니다. 카페에서는 “Could I have a latte, please?”처럼 쓸 수 있어요.'});if(!tips.length&&clean.split(/\s+/).length>=3)tips.push({phrase:'That makes sense.',meaning:'상대의 말을 이해했을 때 대화를 이어가는 표현이에요.',detail:'“그렇군요”, “말이 되네요”라는 뜻으로 상대의 설명에 자연스럽게 반응할 때 씁니다.'});const rec=allWords().filter(w=>new RegExp(`\\b${w.en}\\b`,'i').test(reply)).slice(0,2).map(w=>w.id);addMessage(chatMode,{role:'assistant',text:reply,tips,recommended:rec});renderChat();speak(reply)}catch{showToast('답변을 불러오지 못했어요. 다시 시도해주세요.')}finally{setBusy(false)}}
function clearConversation(){state.chats[chatMode]=[];persist();renderChat();if(chatMode==='scenario')beginScenario()}
function beginScenario(){const s=activeScenario();state.chats.scenario=[{role:'assistant',text:s.opening}];persist();renderChat();speak(s.opening)}
function initSpeech(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){$('#speechStatus').textContent='이 브라우저는 음성 인식을 지원하지 않아요. 문장을 직접 입력해보세요.';$('#micButton').disabled=true;return}recognition=new SR();recognition.lang='en-US';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>{listening=true;$('#micButton').classList.add('recording');$('#speechStatus').textContent='듣고 있어요… 영어로 말해보세요.'};recognition.onresult=e=>{const text=e.results[0][0].transcript;$('#chatInput').value=text;$('#speechStatus').textContent=`인식했어요: “${text}”`;sendChat(text)};recognition.onerror=e=>{$('#speechStatus').textContent=e.error==='not-allowed'?'마이크 권한을 허용해주세요.':'음성을 인식하지 못했어요. 다시 누르거나 직접 입력해보세요.'};recognition.onend=()=>{listening=false;$('#micButton').classList.remove('recording')}}
$('#studyShell').addEventListener('click',e=>{if(e.target.id==='addWord'){const en=$('#newEn').value.trim(),ko=$('#newKo').value.trim();if(!en||!ko){showToast('영어와 뜻을 모두 입력해주세요');return}saveCustomWord(en,ko);showToast('새 단어를 단어장에 추가했어요');studyOrder=[...allWords().filter(x=>state.saved.includes(x.id))];studyIndex=studyOrder.findIndex(x=>x.en===en);studyRevealed=false;renderStudy()}});$$('.nav-item').forEach(b=>b.onclick=()=>go(b.dataset.view));$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#wordSearch').addEventListener('input',renderWords);$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentFilter=b.dataset.filter;renderWords()});$$('.talk-mode').forEach(b=>b.onclick=()=>{const next=b.dataset.mode;if(next===chatMode)return;$$('.talk-mode').forEach(x=>x.classList.toggle('active',x===b));chatMode=next;if(chatMode==='scenario'&&state.chats.scenario.length===0)beginScenario();else renderChat()});$('#scenarioSelect').onchange=()=>beginScenario();$('#sendMessage').onclick=()=>sendChat($('#chatInput').value);$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat($('#chatInput').value)}};$('#micButton').onclick=()=>{if(!recognition)return;if(listening)recognition.stop();else{speechSynthesis.cancel();try{recognition.start()}catch{}}};$('#clearChat').onclick=clearConversation;initSpeech();$('#dateText').textContent=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long'}).format(new Date())+' · 오늘도 좋은 하루예요';renderStats();

// Placement assessment, account profile and result history.
let assessmentData=null,assessmentRun=null,assessmentStep=0;
const SURVEY=[{id:'speakComfort',label:'영어로 자기소개와 일상 이야기를 얼마나 편하게 할 수 있나요?'},{id:'readComfort',label:'영어 안내문이나 짧은 글을 읽고 핵심을 얼마나 이해하나요?'},{id:'writeComfort',label:'영어로 문장이나 짧은 메시지를 얼마나 작성할 수 있나요?'},{id:'studyComfort',label:'영어 문법과 어휘를 얼마나 다양한 상황에서 활용하나요?'}];
async function loadAssessmentData(){if(assessmentData)return assessmentData;try{assessmentData=await fetch('./data/assessment-frameworks.json').then(r=>r.json())}catch{assessmentData={questions:[]}}return assessmentData}
function renderAccountHeader(){const name=$('#accountName'),level=$('#accountLevel'),avatar=$('#accountAvatar');if(!name)return;name.textContent=currentAccount?(currentAccount.split('@')[0]):'게스트';level.textContent=`${state.levelLabel||'초급 입문'} · ${state.level||'A1'}`;avatar.textContent=currentAccount?currentAccount[0].toUpperCase():'나'}
function renderAssessmentIntro(){const latest=state.assessments?.at(-1);$('#assessmentShell').innerHTML=`<article class="assessment-card"><div class="assessment-icon">◎</div><h2>${latest?'현재 수준은 '+latest.level+' · '+latest.label:'처음이라면 먼저 가벼운 수준 진단을 해보세요'}</h2><p>짧은 자기 평가 설문과 어휘·문법·읽기·쓰기·듣기·스피킹 문항으로 권장 난이도를 정해요. 마지막에 결과와 다음 학습 단계를 보여드립니다.</p><div class="assessment-skill-tags"><span>Cambridge CEFR</span><span>Oxford CEFR 어휘 밴드</span><span>IELTS 4 skills</span><span>TOEIC Speaking task 유형</span></div><div class="estimate-note">자체 제작 연습 문항을 사용한 학습용 추정치입니다. Cambridge, Oxford, IELTS, TOEIC의 공식 시험이나 점수 보고서를 대체하지 않습니다.</div><button class="primary-button" id="beginAssessment">${latest?'다시 테스트하고 난이도 바꾸기':'설문 및 진단 시작'} →</button></article><div class="framework-source-links"><a href="https://www.cambridgeenglish.org/exams-and-tests/cefr/" target="_blank" rel="noreferrer">Cambridge CEFR</a><a href="https://www.oxfordlearnersdictionaries.com/about/wordlists/cefr.html" target="_blank" rel="noreferrer">Oxford CEFR word lists</a><a href="https://www.ielts.org/take-a-test/your-results/ielts-scoring-in-detail" target="_blank" rel="noreferrer">IELTS scoring</a><a href="https://www.ets.org/toeic/about/speaking-writing.html" target="_blank" rel="noreferrer">TOEIC Speaking</a></div>`;$('#beginAssessment').onclick=()=>{assessmentRun={survey:{},answers:{},transcripts:{},startedAt:new Date().toISOString()};assessmentStep=-1;renderAssessmentStep()}}
function renderAssessmentStep(){if(assessmentStep===-1){$('#assessmentShell').innerHTML=`<div class="assessment-card"><div class="assessment-progress"><span>목표와 현재 수준</span><span>1 / 2</span></div><h2>영어를 어디에, 어떻게 사용하고 싶나요?</h2><p>몇 가지 선택으로 학습 자료와 난이도를 맞춰볼게요.</p><div class="survey-questions">${[{id:'goal',label:'가장 중요한 학습 목표는 무엇인가요?',options:['일상 회화','여행·해외 생활','업무·면접','시험 준비']},{id:'studyComfort',label:'영어를 사용할 때 현재 어느 정도 편한가요?',options:['기초부터 천천히 시작하고 싶어요','익숙한 주제는 조금 말할 수 있어요','대부분의 상황에서 대화할 수 있어요','복잡한 주제도 자신 있어요']},{id:'studyStyle',label:'어떤 방식의 연습을 더 원하나요?',options:['말하기와 발음','어휘와 문법','읽기와 듣기','쓰기와 표현'] }].map(q=>`<fieldset class="survey-question"><legend>${q.label}</legend><div class="survey-options">${q.options.map((o,i)=>`<label><input type="radio" name="${q.id}" value="${i}"/><span>${o}</span></label>`).join('')}</div></fieldset>`).join('')}</div><button id="startQuestions" class="primary-button">실력 문항 시작 →</button></div>`;$('#startQuestions').onclick=()=>{const survey={};for(const id of ['goal','studyComfort','studyStyle']){const x=$(`input[name="${id}"]:checked`);if(!x){showToast('세 문항에 답해주세요');return}survey[id]=+x.value}assessmentRun.survey=survey;assessmentStep=0;renderAssessmentStep()};return}loadAssessmentData().then(data=>{const qs=data.questions||[];if(assessmentStep>=qs.length){finishAssessment();return}const q=qs[assessmentStep],shown=assessmentStep+1;$('#assessmentShell').innerHTML=`<div class="assessment-card"><div class="assessment-progress"><span>${skillName(q.skill)} 진단</span><span>${shown} / ${qs.length}</span></div><div class="assessment-progressbar"><i style="width:${Math.round(shown/qs.length*100)}%"></i></div><h2>${q.prompt}</h2>${q.type==='audio'?`<button id="assessmentAudio" class="study-secondary">♫ 안내 음성 듣기</button>`:''}${q.options?`<div class="assessment-options">${q.options.map((o,i)=>`<label class="assessment-option"><input type="radio" name="assessmentAnswer" value="${i}"/><span>${String.fromCharCode(65+i)}.</span> ${o}</label>`).join('')}</div>`:`<textarea id="assessmentText" class="assessment-text" placeholder="영어로 답해보세요" rows="4" ${q.type==='speech'?'readonly aria-readonly="true"':''}>${escapeHtml(assessmentRun.answers[q.id]||'')}</textarea>${q.type==='speech'?`<div class="speech-test-row"><button id="assessmentMic" class="study-secondary">🎙 녹음 시작</button><button id="assessmentFinishRecording" class="study-secondary" disabled>대화 마치기</button><span id="assessmentSpeechStatus">마이크를 눌러 말한 뒤, 다 마치면 ‘대화 마치기’를 누르세요.</span></div><div class="assessment-recording-help">음성이 제대로 녹음이 되지 않았나요? <button type="button" id="assessmentRetryRecording" class="text-button">다시 녹음하기</button></div>`:''}<small class="assessment-hint">${q.type==='speech'?'음성 인식 결과는 직접 수정할 수 없어요. 다시 녹음하면 새 결과로 바뀝니다.':`최소 ${q.minWords||8}개 단어로 답해보세요.`}</small>`}<div class="assessment-nav"><button id="assessmentBack" class="study-secondary" ${assessmentStep===0?'disabled':''}>← 이전</button><button id="assessmentNext" class="primary-button">${shown===qs.length?'결과 보기':'다음 →'}</button></div></div>`;$('#assessmentBack').onclick=()=>{if(assessmentStep>0){assessmentStep--;renderAssessmentStep()}};$('#assessmentNext').onclick=()=>saveAssessmentAnswer(q);const mic=$('#assessmentMic'),finish=$('#assessmentFinishRecording'),retry=$('#assessmentRetryRecording');if(mic)mic.onclick=()=>startAssessmentSpeech(q.id);if(finish)finish.onclick=()=>finishAssessmentSpeech(q.id);if(retry)retry.onclick=()=>startAssessmentSpeech(q.id,true);const audio=$('#assessmentAudio');if(audio)audio.onclick=()=>speak(q.audio)})}
function skillName(s){return {vocabulary:'어휘',grammar:'문법',reading:'읽기',writing:'쓰기',speaking:'스피킹'}[s]||s}
function saveAssessmentAnswer(q){let val;if(q.options){const checked=$('input[name="assessmentAnswer"]:checked');if(!checked){showToast('답을 선택해주세요');return}val=+checked.value}else{val=$('#assessmentText').value.trim();if(q.type==='speech'&&!assessmentRun.transcripts[q.id]){showToast('먼저 녹음을 마쳐 음성을 텍스트로 변환해주세요');return}if(val.split(/\s+/).filter(Boolean).length<(q.minWords||8)){showToast(`영어 단어를 ${q.minWords||8}개 이상 말해주세요`);return}}assessmentRun.answers[q.id]=val;assessmentStep++;renderAssessmentStep()}
let assessmentRecognition=null,assessmentInterim='';function finishAssessmentSpeech(id){if(!assessmentRecognition)return;assessmentRecognition.stop();$('#assessmentSpeechStatus').textContent='음성을 문장으로 변환하고 있어요…'}
function startAssessmentSpeech(id,restart=false){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){$('#assessmentSpeechStatus').textContent='이 브라우저는 음성 인식을 지원하지 않아요. Chrome 또는 Edge에서 열어주세요.';return}if(assessmentRecognition){assessmentRecognition.onend=null;try{assessmentRecognition.abort()}catch{}assessmentRecognition=null}assessmentRun.transcripts[id]='';assessmentInterim='';$('#assessmentText').value='';$('#assessmentMic').disabled=true;$('#assessmentFinishRecording').disabled=false;$('#assessmentSpeechStatus').textContent=restart?'다시 녹음 중이에요. 말을 마친 뒤 ‘대화 마치기’를 누르세요.':'녹음 중이에요. 말을 마친 뒤 ‘대화 마치기’를 누르세요.';const r=new SR();assessmentRecognition=r;r.lang='en-US';r.continuous=true;r.interimResults=true;r.maxAlternatives=1;r.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){const text=e.results[i][0].transcript.trim();if(e.results[i].isFinal)assessmentRun.transcripts[id]=`${assessmentRun.transcripts[id]} ${text}`.trim();else assessmentInterim=text}$('#assessmentSpeechStatus').textContent='듣고 있어요… 말이 끝나면 ‘대화 마치기’를 눌러주세요.'};r.onerror=e=>{$('#assessmentSpeechStatus').textContent=e.error==='not-allowed'?'마이크 권한을 허용해주세요.':'음성 녹음이 중단됐어요. 다시 녹음할 수 있어요.';$('#assessmentMic').disabled=false;$('#assessmentFinishRecording').disabled=true};r.onend=()=>{assessmentRecognition=null;const text=assessmentRun.transcripts[id].trim();$('#assessmentMic').disabled=false;$('#assessmentFinishRecording').disabled=true;if(text){$('#assessmentText').value=text;$('#assessmentSpeechStatus').textContent=`변환 완료 · ${text}`}else{$('#assessmentSpeechStatus').textContent='음성이 제대로 녹음이 되지 않았나요? 다시 녹음해 주세요.'}};try{r.start()}catch{$('#assessmentMic').disabled=false;$('#assessmentFinishRecording').disabled=true;$('#assessmentSpeechStatus').textContent='마이크를 시작하지 못했어요. 다시 시도해주세요.'}}
function finishAssessment(){const qs=assessmentData.questions,skill={vocabulary:{got:0,total:0},grammar:{got:0,total:0},reading:{got:0,total:0},writing:{got:0,total:0},speaking:{got:0,total:0},listening:{got:0,total:0}};let points=0;for(const q of qs){let p=0;if(q.options){skill[q.skill].total++;if(assessmentRun.answers[q.id]===q.answer){p=1;skill[q.skill].got++;points++}}else{skill[q.skill].total+=2;const text=String(assessmentRun.answers[q.id]||''),wc=text.split(/\s+/).filter(Boolean).length,sentences=(text.match(/[.!?]/g)||[]).length;p=Math.min(2,Math.floor(wc/(q.minWords||8))+(sentences>1?1:0));skill[q.skill].got+=p;points+=p/2}}const avg=Number(assessmentRun.survey.studyComfort||0),testIndex=Math.min(5,Math.floor(points/qs.length*6)),surveyIndex=Math.round(avg/3*5),index=Math.max(0,Math.min(5,Math.round(testIndex*.75+surveyIndex*.25))),level=CEFR[index];for(const s of Object.values(skill))s.percent=s.total?Math.round(s.got/s.total*100):0;const result={id:crypto.randomUUID(),date:new Date().toISOString(),level,label:CEFR_KO[index],index,skill,estimates:{IELTS:['2.5–3.0','3.5–4.0','4.5–5.0','5.5–6.5','7.0–8.0','8.5–9.0'][index],TOEICSpeaking:[25,55,90,125,165,190][index]},correct:Math.round(points),questionCount:qs.length,survey:assessmentRun.survey,answers:assessmentRun.answers};state.assessments=state.assessments||[];state.assessments.push(result);state.level=level;state.levelLabel=CEFR_KO[index];state.manualLevel=false;assessmentRun=null;persist();go('result')}
function renderLatestResult(){const r=state._historicalView||state.assessments?.at(-1);state._historicalView=null;if(!r){$('#resultShell').innerHTML=`<div class="assessment-card"><h2>아직 진단 결과가 없어요</h2><p>설문과 테스트를 완료하면 결과를 보여드려요.</p><button class="primary-button" data-result-go="assessment">수준 진단 시작 →</button></div>`;$('#resultShell').querySelector('[data-result-go]').onclick=()=>go('assessment');return}const skills=Object.entries(r.skill||{}).map(([k,v])=>`<div class="skill-score"><div><b>${skillName(k)}</b><span>${v.percent}%</span></div><div class="score-track"><i style="width:${v.percent}%"></i></div></div>`).join('');const next=CEFR[Math.min(5,r.index+1)];$('#resultShell').innerHTML=`<div class="result-hero"><div class="result-level">${r.level}</div><div><span class="eyebrow">추천 학습 등급</span><h2>${r.label} · ${r.correct}/${r.questionCount}</h2><p>진단 결과에 맞춰 ${r.level} 과정으로 학습 난이도를 설정했어요.</p></div></div><div class="result-columns"><article class="result-panel"><h3>영역별 결과</h3>${skills}</article><article class="result-panel"><h3>시험 체계 참고 추정</h3><p><b>IELTS 밴드 참고</b><span>${r.estimates.IELTS}</span></p><p><b>TOEIC Speaking 점수 참고</b><span>${r.estimates.TOEICSpeaking} / 200</span></p><div class="estimate-note">공식 점수 예측이 아닌 학습용 대략 환산입니다. 실제 시험은 공식 채점과 운영 절차를 따릅니다.</div></article></div><article class="result-panel recommendation-panel"><h3>${r.level} 맞춤 학습 추천</h3><p>어휘는 Oxford CEFR 밴드, 문법·읽기·쓰기는 Cambridge CEFR 및 IELTS 기술 기준, 스피킹은 Cambridge CEFR can-do 기술과 TOEIC Speaking의 직장·일상 과제 유형을 참고한 자체 연습으로 이어집니다.</p><div class="recommendation-actions"><button class="primary-button" data-result-go="home">이 난이도로 학습하기 →</button><button class="study-secondary" data-result-go="assessment">난이도 다시 진단</button><button class="study-secondary" data-result-go="mypage">히스토리 보기</button></div><small>다음 추천 단계: ${next}</small></article>`;$$('[data-result-go]').forEach(b=>b.onclick=()=>go(b.dataset.resultGo))}
function renderMyPage(){const history=[...(state.assessments||[])].reverse(),accountArea=currentAccount?`<div class="account-summary"><div class="avatar">${currentAccount[0].toUpperCase()}</div><div><b>${escapeHtml(currentAccount)}</b><small>이 브라우저에 저장된 계정</small></div><div class="account-actions"><button id="exportAccountBackup" class="study-secondary">계정 백업 저장</button><button id="logoutButton" class="study-secondary">로그아웃</button></div></div><section class="account-card account-edit-card"><h2>계정 정보 수정</h2><p>표시 이름과 복구 이메일을 관리하고, 현재 비밀번호를 확인한 뒤 변경할 수 있어요.</p><form id="profileForm"><label>표시 이름<input name="displayName" maxlength="40" value="${escapeHtml(JSON.parse(localStorage.getItem(AUTH_KEY)||'{}')[currentAccount]?.profile?.displayName||currentAccount.split('@')[0])}" required/></label><label>복구 이메일<input name="recoveryEmail" type="email" placeholder="name@example.com" value="${escapeHtml(JSON.parse(localStorage.getItem(AUTH_KEY)||'{}')[currentAccount]?.profile?.email||'')}"/></label><div id="profileMessage" class="auth-error"></div><button class="study-secondary">계정 정보 저장</button></form><form id="passwordForm"><h3>비밀번호 변경</h3><label>현재 비밀번호<input name="currentPassword" type="password" autocomplete="current-password" required/></label><label>새 비밀번호<input name="newPassword" type="password" minlength="8" autocomplete="new-password" required/></label><label>새 비밀번호 확인<input name="confirmPassword" type="password" minlength="8" autocomplete="new-password" required/></label><div id="passwordMessage" class="auth-error"></div><button class="primary-button">비밀번호 변경</button></form><div class="reset-panel"><h3>비밀번호를 잊으셨나요?</h3><p>등록된 이메일로 인증 코드를 받아 비밀번호를 재설정합니다.</p><form id="resetRequestForm"><label>계정 아이디<input name="accountId" value="${escapeHtml(currentAccount)}" required/></label><label>이메일<input name="email" type="email" value="${escapeHtml(JSON.parse(localStorage.getItem(AUTH_KEY)||'{}')[currentAccount]?.profile?.email||'')}" required/></label><button class="study-secondary">인증 코드 받기</button></form><form id="resetConfirmForm"><label>인증 코드<input name="code" inputmode="numeric" required/></label><label>새 비밀번호<input name="password" type="password" minlength="8" required/></label><button class="primary-button">비밀번호 재설정</button></form><div id="resetMessage" class="auth-error"></div><div class="estimate-note">현재 공개 배포본은 정적 웹앱이라 이메일 발송·인증 서버가 아직 연결되지 않았습니다. 서버 API가 설정되면 실제 인증을 요청하며, 설정되지 않은 경우 인증이 완료된 것처럼 표시하지 않습니다.</div></div></section>`:`<section class="account-card"><h2>계정으로 학습 기록 저장</h2><button id="importAccountBackup" class="study-secondary">기존 계정 백업 가져오기</button><input id="accountBackupFile" type="file" accept="application/json,.json" hidden/><p>가입하거나 로그인하면 이 브라우저에서 계정별 단어장과 진단 기록을 나눠 저장합니다.</p><div class="auth-tabs"><button class="auth-tab active" data-auth-mode="signup">회원가입</button><button class="auth-tab" data-auth-mode="login">로그인</button></div><form id="authForm"><label>아이디<input name="email" type="text" required minlength="3" maxlength="40" placeholder="사용할 아이디" autocomplete="username"/></label><label>비밀번호<input name="password" type="password" minlength="8" required placeholder="8자 이상" autocomplete="current-password"/></label><button type="button" id="forgotPasswordLink" class="text-button">비밀번호를 잊으셨나요?</button><div id="authError" class="auth-error"></div><button class="primary-button" id="authSubmit">회원가입</button></form><div id="guestResetPanel" class="reset-panel" hidden><h3>이메일 인증으로 비밀번호 재설정</h3><form id="guestResetRequest"><label>계정 아이디<input name="accountId" required/></label><label>복구 이메일<input name="email" type="email" required/></label><button class="study-secondary">인증 코드 받기</button></form><form id="guestResetConfirm"><label>인증 코드<input name="code" inputmode="numeric" required/></label><label>새 비밀번호<input name="password" type="password" minlength="8" required/></label><button class="primary-button">비밀번호 재설정</button></form><div id="guestResetMessage" class="auth-error"></div><div class="estimate-note">이메일 발송은 서버 연결 뒤 사용할 수 있습니다.</div></div><div class="estimate-note">현재 계정은 이 브라우저에만 저장됩니다. 다른 기기 동기화를 켜려면 별도 인증·데이터베이스 서버를 연결해야 합니다.</div></section>`;$('#mypageShell').innerHTML=`${accountArea}<div class="mypage-grid"><article class="result-panel"><h3>현재 학습 설정</h3><div class="current-level"><b>${state.level||'A1'}</b><span>${state.levelLabel||'초급 입문'}${state.manualLevel?' · 직접 선택':' · 진단 추천'}</span></div><p>다시 진단하거나 직접 학습 난이도를 선택할 수 있어요.</p><label class="level-select-label">학습 난이도<select id="manualLevel">${CEFR.map((l,i)=>`<option value="${l}" ${state.level===l?'selected':''}>${l} · ${CEFR_KO[i]}</option>`).join('')}</select></label><button id="saveLevel" class="study-secondary">난이도 저장</button><button id="retakeTest" class="primary-button">테스트 다시 보기</button></article><article class="result-panel history-panel"><h3>진단 결과 히스토리 <span>${history.length}회</span></h3>${history.length?`<div class="history-list">${history.map(h=>`<button class="history-item" data-history="${h.id}"><span class="history-date">${new Date(h.date).toLocaleDateString('ko-KR')}</span><b>${h.level} · ${h.label}</b><small>${h.correct}/${h.questionCount} · IELTS ${h.estimates.IELTS}</small><span>→</span></button>`).join('')}</div>`:'<p class="empty-history">테스트를 완료하면 결과가 회차별로 여기에 쌓여요.</p>'}</article></div><div class="account-data-note">학습 기록은 브라우저 기기별로 저장됩니다. 현재는 다른 기기 간 서버 동기화가 활성화되어 있지 않습니다.</div>`;if(currentAccount){$('#logoutButton').onclick=logoutAccount;$('#exportAccountBackup').onclick=exportAccountBackup;$('#profileForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),accounts=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}'),a=accounts[currentAccount];a.profile={...(a.profile||{}),displayName:String(fd.get('displayName')).trim(),email:String(fd.get('recoveryEmail')).trim().toLowerCase()};localStorage.setItem(AUTH_KEY,JSON.stringify(accounts));$('#profileMessage').textContent='계정 정보를 저장했어요.'};$('#passwordForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),accounts=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}'),a=accounts[currentAccount],msg=$('#passwordMessage');if(await passwordHash(fd.get('currentPassword'),new Uint8Array(a.salt))!==a.hash){msg.textContent='현재 비밀번호가 맞지 않아요.';return}if(fd.get('newPassword')!==fd.get('confirmPassword')){msg.textContent='새 비밀번호가 서로 달라요.';return}const salt=crypto.getRandomValues(new Uint8Array(16));a.salt=Array.from(salt);a.hash=await passwordHash(fd.get('newPassword'),salt);localStorage.setItem(AUTH_KEY,JSON.stringify(accounts));msg.textContent='비밀번호를 변경했어요.';e.target.reset()};$('#resetRequestForm').onsubmit=async e=>{e.preventDefault();await requestPasswordReset(new FormData(e.target),$('#resetMessage'))};$('#resetConfirmForm').onsubmit=async e=>{e.preventDefault();await confirmPasswordReset(new FormData(e.target),$('#resetMessage'))}}else{initAuthForm();$('#importAccountBackup').onclick=()=>$('#accountBackupFile').click();$('#accountBackupFile').onchange=importAccountBackup;$('#forgotPasswordLink').onclick=()=>{$('#guestResetPanel').hidden=!$('#guestResetPanel').hidden;$('#guestResetRequest [name=accountId]').value=$('#authForm [name="email"]').value.trim()};$('#guestResetRequest').onsubmit=async e=>{e.preventDefault();await requestPasswordReset(new FormData(e.target),$('#guestResetMessage'))};$('#guestResetConfirm').onsubmit=async e=>{e.preventDefault();await confirmPasswordReset(new FormData(e.target),$('#guestResetMessage'))}}$('#saveLevel').onclick=()=>{const l=$('#manualLevel').value;state.level=l;state.levelLabel=CEFR_KO[CEFR.indexOf(l)];state.manualLevel=true;persist();renderMyPage();showToast('학습 난이도를 변경했어요')};$('#retakeTest').onclick=()=>go('assessment');$$('[data-history]').forEach(b=>b.onclick=()=>{state._historicalView=state.assessments.find(r=>r.id===b.dataset.history);go('result')})}
function exportAccountBackup(){const accounts=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}'),account=accounts[currentAccount];if(!account){showToast('저장할 계정이 없어요');return}const backup={format:'daily-english-account-backup-v1',createdAt:new Date().toISOString(),accountId:currentAccount,account:{salt:account.salt,hash:account.hash,createdAt:account.createdAt,profile:account.profile||{}},data:state};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`daily-english-${currentAccount.replace(/[^a-z0-9_-]/gi,'_')}-backup.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);showToast('계정 백업 파일을 다운로드했어요. 안전한 위치에 보관해주세요.')}
async function importAccountBackup(event){const file=event.target.files?.[0];if(!file)return;try{const backup=JSON.parse(await file.text());if(backup.format!=='daily-english-account-backup-v1'||!backup.accountId||!backup.account?.salt||!backup.account?.hash||!backup.data)throw Error('백업 파일 형식이 맞지 않아요.');const id=normalizeAccountId(backup.accountId),accounts=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}');accounts[id]={...backup.account,data:backup.data,restoredAt:new Date().toISOString()};localStorage.setItem(AUTH_KEY,JSON.stringify(accounts));localStorage.setItem(`${STORE}.${id}`,JSON.stringify(backup.data));currentAccount=id;sessionStorage.setItem('dailyEnglish.session',id);state={...initial,...backup.data,chats:{...initial.chats,...(backup.data.chats||{})}};renderAccountHeader();renderMyPage();renderStats();showToast(`${id} 계정과 학습 기록을 이 Chrome 프로필에 복원했어요.`)}catch(error){showToast(error.message||'백업을 읽지 못했어요.');event.target.value=''}}
async function requestPasswordReset(form,msg){try{const res=await fetch('/api/auth/password-reset/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:String(form.get('accountId')).trim(),email:String(form.get('email')).trim().toLowerCase()})});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.message||'인증 서버에 연결할 수 없습니다.');msg.textContent=data.message||'등록된 이메일로 인증 코드를 보냈어요.'}catch{msg.textContent='이메일 인증 서버가 아직 연결되지 않았어요. 발송된 인증 코드는 없습니다.'}}
async function confirmPasswordReset(form,msg){try{const res=await fetch('/api/auth/password-reset/confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:form.closest('.reset-panel').querySelector('form [name="accountId"]').value,email:form.closest('.reset-panel').querySelector('form [name="email"]').value,code:String(form.get('code')).trim(),password:String(form.get('password'))})});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(data.message||'인증 서버에 연결할 수 없습니다.');msg.textContent=data.message||'비밀번호를 재설정했어요.'}catch{msg.textContent='이메일 인증 서버가 아직 연결되지 않았어요. 비밀번호는 변경되지 않았습니다.'}}
function initAuthForm(){let mode='signup';$$('[data-auth-mode]').forEach(b=>b.onclick=()=>{$$('.auth-tab').forEach(x=>x.classList.toggle('active',x===b));mode=b.dataset.authMode;$('#authSubmit').textContent=mode==='signup'?'회원가입':'로그인'});$('#authForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),email=fd.get('email').toLowerCase().trim(),password=fd.get('password'),accounts=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}');if(mode==='signup'){if(accounts[email]){$('#authError').textContent='이미 가입된 이메일이에요.';return}const salt=crypto.getRandomValues(new Uint8Array(16)),hash=await passwordHash(password,salt);accounts[email]={salt:Array.from(salt),hash,createdAt:new Date().toISOString(),data:state};localStorage.setItem(AUTH_KEY,JSON.stringify(accounts))}else{const a=accounts[email];if(!a||await passwordHash(password,new Uint8Array(a.salt))!==a.hash){$('#authError').textContent='이메일 또는 비밀번호를 확인해주세요.';return}state={...initial,...a.data,chats:{...initial.chats,...(a.data.chats||{})}}}currentAccount=email;sessionStorage.setItem('dailyEnglish.session',email);localStorage.setItem(`${STORE}.${email}`,JSON.stringify(state));renderAccountHeader();persist();renderMyPage();showToast(mode==='signup'?'계정을 만들었어요':'로그인했어요')}}
function normalizeAccountId(value){return String(value||'').trim().toLowerCase().normalize('NFKC')}
function accountCandidates(accounts,id){const normalized=normalizeAccountId(id),legacy=normalized.includes('@')?normalized:`${normalized}@gmail.com`,base=normalized.split('@')[0],keys=Object.keys(accounts),localPartMatches=keys.filter(key=>normalizeAccountId(key).split('@')[0]===base);return [normalized,legacy,...localPartMatches].filter((key,index,all)=>accounts[key]&&all.indexOf(key)===index)}
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:120000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('')}
function logoutAccount(){persist();currentAccount=null;sessionStorage.removeItem('dailyEnglish.session');try{const old=JSON.parse(localStorage.getItem(STORE)||'{}');state={...initial,...old,chats:{...initial.chats,...(old.chats||{})}}}catch{state={...initial}}renderAccountHeader();renderMyPage();renderStats()}
