function initAuthForm(){let mode=nextAuthMode;$$('[data-auth-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.authMode===mode);b.onclick=()=>{$$('.auth-tab').forEach(x=>x.classList.toggle('active',x===b));mode=b.dataset.authMode;$('#authSubmit').textContent=mode==='signup'?'회원가입':'로그인'}});$('#authSubmit').textContent=mode==='signup'?'회원가입':'로그인';$('#authForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),typedId=normalizeAccountId(fd.get('email')),password=fd.get('password'),accounts=JSON.parse(localStorage.getItem(AUTH_KEY)||'{}');if(mode==='signup'){if(accounts[typedId]){$('#authError').textContent='이미 사용 중인 아이디예요.';return}const salt=crypto.getRandomValues(new Uint8Array(16)),hash=await passwordHash(password,salt);accounts[typedId]={salt:Array.from(salt),hash,createdAt:new Date().toISOString(),data:state};localStorage.setItem(AUTH_KEY,JSON.stringify(accounts));currentAccount=typedId;sessionStorage.setItem('dailyEnglish.session',typedId);persist();renderAccountHeader();showToast('가입됐어요. 이제 수준 진단을 시작해요.');nextAuthMode='login';go('assessment')}else{const matches=accountCandidates(accounts,typedId);let matchedKey=null;for(const key of matches){const candidate=accounts[key];if(candidate?.salt&&candidate?.hash&&await passwordHash(password,new Uint8Array(candidate.salt))===candidate.hash){matchedKey=key;break}}if(!matchedKey){$('#authError').textContent='아이디 또는 비밀번호를 확인해주세요. 가입할 때 사용한 아이디 표기(이메일 포함 여부)와 비밀번호를 다시 확인해주세요.';return}const a=accounts[matchedKey],canonical=normalizeAccountId(matchedKey);state={...initial,...a.data,chats:{...initial.chats,...(a.data?.chats||{})}};currentAccount=canonical;sessionStorage.setItem('dailyEnglish.session',canonical);localStorage.setItem(`${STORE}.${canonical}`,JSON.stringify(state));renderAccountHeader();persist();showToast('로그인했어요');go('home')}}}
