 $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumbTitle').textContent=titleMap[view]||'오늘의 학습';window.scrollTo({top:0,behavior:'smooth'});
 if(view==='words'){wordPage=0;$('#wordSearch').oninput=()=>{wordPage=0;renderWords()};renderWords()}
